<?php
session_start(); date_default_timezone_set('Asia/Jakarta');
require_once __DIR__ . '/../../../../koneksi.php'; require_once __DIR__ . '/../../../../koneksi3.php';
header('Content-Type: application/json; charset=utf-8');
function canReportErp($conn): bool { $s=sqlsrv_query($conn,"SELECT CanView FROM dbo.SMGroupTrustee WHERE GroupId=? AND MenuId=212",[$_SESSION['GroupId']??0]); return $s&&($r=sqlsrv_fetch_array($s,SQLSRV_FETCH_ASSOC))&&(int)($r['CanView']??0)===1; }
function erpDate($v): string { if(!$v)return '-'; $t=strtotime((string)$v); return $t?date('d/m/Y',$t):'-'; }
function erpNum($v): string { return $v === null || $v === '' ? '-' : number_format((float)$v, 2, '.', ','); }
if(!isset($_SESSION['UserName'])||!canReportErp($conn)){ http_response_code(403); echo json_encode(['data'=>[]]); exit; }
$cpList=$_POST['cp']??[]; if(!is_array($cpList))$cpList=[]; $cpList=array_values(array_filter(array_unique(array_map(fn($v)=>strtoupper(trim((string)$v)),$cpList)))); $cpList=array_slice($cpList,0,25); if(!$cpList){ echo json_encode(['data'=>[]]); exit; }
$out=[];
try{
  $keys=[];$params=[]; foreach($cpList as $i=>$cp){$k=':cp_'.$i;$keys[]=$k;$params[$k]=$cp;} $ph=implode(',',$keys);
  $sql="WITH latest_cp AS (SELECT TRIM(CAST(prdnmbr AS TEXT)) cp_no,productionhdid,ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(CAST(prdnmbr AS TEXT))) ORDER BY prddate DESC NULLS LAST,productionhdid DESC) rn FROM pdproductionhd WHERE UPPER(TRIM(CAST(prdnmbr AS TEXT))) IN ($ph)), latest AS (SELECT cp_no,productionhdid FROM latest_cp WHERE rn=1), celup AS (SELECT DISTINCT ON (l.cp_no) l.cp_no,r.starttime tgl_celup_padd FROM latest l JOIN pdproductionrtg r ON r.productionhdid=l.productionhdid WHERE r.rtgmsid IN (838,842,555,556,559,809) AND r.starttime IS NOT NULL ORDER BY l.cp_no,r.rtgseq ASC NULLS LAST,r.starttime ASC NULLS LAST,r.productionrtgid ASC), aktual AS (SELECT DISTINCT ON (l.cp_no) l.cp_no,r.prdqty aktual_qty FROM latest l JOIN pdproductionrtg r ON r.productionhdid=l.productionhdid WHERE r.rtgmsid=409 AND r.prdqty IS NOT NULL ORDER BY l.cp_no,r.rtgseq ASC NULLS LAST,r.productionrtgid ASC), last_filled AS (SELECT DISTINCT ON (l.cp_no) l.cp_no,r.rtgseq,r.rtgmsid FROM latest l JOIN pdproductionrtg r ON r.productionhdid=l.productionhdid WHERE COALESCE(r.prdqty,0)>0 OR r.prduomid IS NOT NULL OR COALESCE(r.prdstdqty,0)>0 ORDER BY l.cp_no,r.rtgseq DESC NULLS LAST,r.productionrtgid DESC), posisi AS (SELECT l.cp_no,CASE WHEN lf.rtgmsid=692 THEN 'VERPACKING' WHEN COALESCE(next_m.rtgname,'')<>'' THEN next_m.rtgname WHEN COALESCE(first_m.rtgname,'')<>'' THEN first_m.rtgname ELSE 'PEMARTAIAN' END posisi_hari_ini FROM latest l LEFT JOIN last_filled lf ON lf.cp_no=l.cp_no LEFT JOIN pdproductionrtg next_r ON next_r.productionhdid=l.productionhdid AND next_r.rtgseq=lf.rtgseq+1 LEFT JOIN pdrtgms next_m ON next_m.rtgmsid=next_r.rtgmsid LEFT JOIN pdproductionrtg first_r ON first_r.productionhdid=l.productionhdid AND first_r.rtgmsid=409 LEFT JOIN pdrtgms first_m ON first_m.rtgmsid=first_r.rtgmsid), acc AS (SELECT DISTINCT ON (l.cp_no) l.cp_no,r.starttime acc_tgl,COALESCE(r.failmsid,0) failmsid,COALESCE(r.fgresult,'') fgresult,COALESCE(f.failcode,'') failcode,COALESCE(f.faildesc,'') faildesc FROM latest l JOIN pdproductionrtg r ON r.productionhdid=l.productionhdid AND r.rtgmsid=589 LEFT JOIN pdfailms f ON f.failmsid=r.failmsid ORDER BY l.cp_no,CASE WHEN r.failmsid IS NOT NULL AND r.failmsid<>0 THEN 0 ELSE 1 END ASC,r.starttime DESC NULLS LAST,r.productionrtgid DESC) SELECT l.cp_no,c.tgl_celup_padd,ak.aktual_qty,p.posisi_hari_ini,a.acc_tgl,a.failmsid,a.fgresult,a.failcode,a.faildesc FROM latest l LEFT JOIN celup c ON c.cp_no=l.cp_no LEFT JOIN aktual ak ON ak.cp_no=l.cp_no LEFT JOIN posisi p ON p.cp_no=l.cp_no LEFT JOIN acc a ON a.cp_no=l.cp_no";
  $st=$conn3->prepare($sql); $st->execute($params); while($r=$st->fetch(PDO::FETCH_ASSOC)){ $fail=(int)($r['failmsid']??0); $fg=strtoupper(trim((string)($r['fgresult']??''))); $has=trim((string)($r['failcode']??''))!==''||trim((string)($r['faildesc']??''))!==''; $status='-'; if($fail!==0&&$has)$status='Fail'; elseif($fg==='P'&&$fail===0&&!$has)$status='Pass'; $out[strtoupper(trim((string)$r['cp_no']))]=['tgl_celup_padd'=>erpDate($r['tgl_celup_padd']??null),'aktual_qty'=>erpNum($r['aktual_qty']??null),'posisi_hari_ini'=>trim((string)($r['posisi_hari_ini']??''))?:'-','acc_warna_r_status'=>$status,'acc_warna_r_tgl'=>erpDate($r['acc_tgl']??null)]; }
}catch(Throwable $e){ error_log('report lazy ERP error: '.$e->getMessage()); }
echo json_encode(['data'=>$out]);
